<?php
require_once __DIR__.'/../config/session.php';require_once __DIR__.'/../config/auth.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../config/helper.php';
check_access([1]);$db=Database::getInstance();
$success=$_SESSION['operasional_success']??'';$error=$_SESSION['operasional_error']??'';unset($_SESSION['operasional_success'],$_SESSION['operasional_error']);

if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!verify_csrf($_POST['csrf_token']??'')){$_SESSION['operasional_error']='Token keamanan tidak valid. Silakan muat ulang halaman.';redirect('kontrol_operasional.php');}
 $action=$_POST['action']??'';
 try{
  if($action==='tutup_sesi'){
   $sesi_id=(int)($_POST['sesi_id']??0);
   $stmt=$db->prepare("SELECT sa.id,sa.pertemuan_ke,sa.status,g.nama_lengkap nama_guru,m.nama_mapel,k.nama_kelas FROM sesi_absensi sa JOIN pengajaran p ON p.id=sa.pengajaran_id JOIN guru g ON g.id=p.guru_id JOIN mapel m ON m.id=p.mapel_id JOIN kelas k ON k.id=p.kelas_id WHERE sa.id=?");$stmt->execute([$sesi_id]);$target=$stmt->fetch();
   if(!$target||$target['status']!=='Dibuka')throw new RuntimeException('Sesi tidak ditemukan atau sudah ditutup.');
   if(!tutup_sesi_absensi($db,$sesi_id))throw new RuntimeException('Sesi sudah diproses oleh pengguna lain.');
   $log="[OPERASIONAL ADMIN] Menutup sesi absensi ID $sesi_id | {$target['nama_guru']} | {$target['nama_mapel']} | {$target['nama_kelas']} | Pertemuan {$target['pertemuan_ke']}";
   catat_log($_SESSION['user_id'],$log);$_SESSION['operasional_success']='Sesi absensi berhasil ditutup dan siswa yang belum check-in dicatat Alpa.';
  }elseif($action==='sinkron_sesi'){
   $sesi_id=(int)($_POST['sesi_id']??0);$db->beginTransaction();
   $stmt=$db->prepare("SELECT sa.id,sa.pertemuan_ke,p.kelas_id,g.nama_lengkap nama_guru,m.nama_mapel,k.nama_kelas FROM sesi_absensi sa JOIN pengajaran p ON p.id=sa.pengajaran_id JOIN guru g ON g.id=p.guru_id JOIN mapel m ON m.id=p.mapel_id JOIN kelas k ON k.id=p.kelas_id WHERE sa.id=? AND sa.status='Ditutup' FOR UPDATE");$stmt->execute([$sesi_id]);$target=$stmt->fetch();
   if(!$target)throw new RuntimeException('Sesi tertutup tidak ditemukan.');
   $stmt=$db->prepare("INSERT INTO detail_absensi(sesi_absensi_id,siswa_id,status,keterangan) SELECT ?,s.id,'Alpa','Disinkronkan oleh Admin karena belum tercatat' FROM siswa s WHERE s.kelas_id=? AND NOT EXISTS(SELECT 1 FROM detail_absensi da WHERE da.sesi_absensi_id=? AND da.siswa_id=s.id)");
   $stmt->execute([$sesi_id,$target['kelas_id'],$sesi_id]);$jumlah=$stmt->rowCount();$db->commit();
   catat_log($_SESSION['user_id'],"[OPERASIONAL ADMIN] Sinkronisasi sesi absensi ID $sesi_id | {$target['nama_guru']} | {$target['nama_mapel']} | {$target['nama_kelas']} | $jumlah siswa ditambahkan sebagai Alpa");
   $_SESSION['operasional_success']=$jumlah?"Sinkronisasi selesai. $jumlah siswa ditambahkan sebagai Alpa.":'Sesi sudah lengkap; tidak ada data yang perlu ditambahkan.';
  }elseif($action==='atur_akses'){
   $pengajaran_id=(int)($_POST['pengajaran_id']??0);$pertemuan=(int)($_POST['pertemuan_ke']??0);$status=$_POST['status']??'';
   if($pertemuan<1||$pertemuan>20||!in_array($status,['Dibuka','Dikunci'],true))throw new RuntimeException('Pertemuan atau status akses tidak valid.');
   $stmt=$db->prepare('SELECT p.id,g.nama_lengkap nama_guru,m.nama_mapel,k.nama_kelas FROM pengajaran p JOIN guru g ON g.id=p.guru_id JOIN mapel m ON m.id=p.mapel_id JOIN kelas k ON k.id=p.kelas_id WHERE p.id=?');$stmt->execute([$pengajaran_id]);$target=$stmt->fetch();if(!$target)throw new RuntimeException('Pengajaran tidak ditemukan.');
   $db->beginTransaction();$stmt=$db->prepare('SELECT status FROM akses_pertemuan WHERE pengajaran_id=? AND pertemuan_ke=? FOR UPDATE');$stmt->execute([$pengajaran_id,$pertemuan]);$status_lama=$stmt->fetchColumn()?:'Dikunci (default)';
   $stmt=$db->prepare("INSERT INTO akses_pertemuan(pengajaran_id,pertemuan_ke,status,dibuka_pada) VALUES(?,?,?,CASE WHEN ?='Dibuka' THEN NOW() ELSE NULL END) ON DUPLICATE KEY UPDATE status=VALUES(status),dibuka_pada=CASE WHEN VALUES(status)='Dibuka' THEN NOW() ELSE NULL END");$stmt->execute([$pengajaran_id,$pertemuan,$status,$status]);$db->commit();
   catat_log($_SESSION['user_id'],"[OPERASIONAL ADMIN] Akses pertemuan diubah $status_lama -> $status | {$target['nama_guru']} | {$target['nama_mapel']} | {$target['nama_kelas']} | Pertemuan $pertemuan");
   $_SESSION['operasional_success']="Akses pertemuan $pertemuan berhasil diubah menjadi $status.";
  }else throw new RuntimeException('Aksi operasional tidak dikenali.');
 }catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log('Kontrol operasional gagal: '.$e->getMessage());$_SESSION['operasional_error']=$e instanceof RuntimeException?$e->getMessage():'Tindakan operasional gagal diproses.';}
 redirect('kontrol_operasional.php');
}

$pengajaran=$db->query('SELECT p.id,p.semester,p.tahun_ajaran,g.nama_lengkap nama_guru,m.nama_mapel,k.nama_kelas FROM pengajaran p JOIN guru g ON g.id=p.guru_id JOIN mapel m ON m.id=p.mapel_id JOIN kelas k ON k.id=p.kelas_id ORDER BY g.nama_lengkap,k.nama_kelas,m.nama_mapel,p.tahun_ajaran DESC')->fetchAll();
$sesi_terbuka=$db->query("SELECT sa.id,sa.pertemuan_ke,sa.tanggal,sa.waktu_buka,sa.waktu_tutup,IF(sa.waktu_tutup<NOW(),1,0) kedaluwarsa,g.nama_lengkap nama_guru,m.nama_mapel,k.nama_kelas,(SELECT COUNT(*) FROM detail_absensi da WHERE da.sesi_absensi_id=sa.id) tercatat,(SELECT COUNT(*) FROM siswa s WHERE s.kelas_id=p.kelas_id) total_siswa FROM sesi_absensi sa JOIN pengajaran p ON p.id=sa.pengajaran_id JOIN guru g ON g.id=p.guru_id JOIN mapel m ON m.id=p.mapel_id JOIN kelas k ON k.id=p.kelas_id WHERE sa.status='Dibuka' ORDER BY kedaluwarsa DESC,sa.waktu_tutup")->fetchAll();
$sesi_tidak_lengkap=$db->query("SELECT sa.id,sa.pertemuan_ke,sa.tanggal,g.nama_lengkap nama_guru,m.nama_mapel,k.nama_kelas,(SELECT COUNT(*) FROM siswa s WHERE s.kelas_id=p.kelas_id) total_siswa,(SELECT COUNT(*) FROM detail_absensi da WHERE da.sesi_absensi_id=sa.id) tercatat FROM sesi_absensi sa JOIN pengajaran p ON p.id=sa.pengajaran_id JOIN guru g ON g.id=p.guru_id JOIN mapel m ON m.id=p.mapel_id JOIN kelas k ON k.id=p.kelas_id WHERE sa.status='Ditutup' AND EXISTS(SELECT 1 FROM siswa s WHERE s.kelas_id=p.kelas_id AND NOT EXISTS(SELECT 1 FROM detail_absensi da WHERE da.sesi_absensi_id=sa.id AND da.siswa_id=s.id)) ORDER BY sa.tanggal DESC LIMIT 50")->fetchAll();
$akses_terbuka=$db->query("SELECT ap.pengajaran_id,ap.pertemuan_ke,ap.dibuka_pada,g.nama_lengkap nama_guru,m.nama_mapel,k.nama_kelas FROM akses_pertemuan ap JOIN pengajaran p ON p.id=ap.pengajaran_id JOIN guru g ON g.id=p.guru_id JOIN mapel m ON m.id=p.mapel_id JOIN kelas k ON k.id=p.kelas_id WHERE ap.status='Dibuka' ORDER BY ap.dibuka_pada DESC,ap.id DESC")->fetchAll();
$stmt=$db->prepare("SELECT l.created_at,u.username,l.aktivitas,l.ip_address FROM log_aktivitas l LEFT JOIN users u ON u.id=l.user_id WHERE l.aktivitas LIKE '[OPERASIONAL ADMIN]%' ORDER BY l.created_at DESC,l.id DESC LIMIT 20");$stmt->execute();$audit_operasional=$stmt->fetchAll();
$kedaluwarsa=count(array_filter($sesi_terbuka,static fn($s)=>(int)$s['kedaluwarsa']===1));
require_once __DIR__.'/../includes/header.php';require_once __DIR__.'/../includes/sidebar.php';
?>
