<div class="row g-2 mb-3"><?php foreach([['Sesi Terbuka',count($sesi_terbuka),'fa-door-open','primary'],['Sesi Kedaluwarsa',$kedaluwarsa,'fa-clock','danger'],['Data Tidak Lengkap',count($sesi_tidak_lengkap),'fa-triangle-exclamation','warning'],['Akses Terbuka',count($akses_terbuka),'fa-lock-open','success']] as [$label,$jumlah,$icon,$warna]): ?><div class="col-6 col-xl-3"><div class="card metric-card p-3"><div class="d-flex align-items-center gap-3"><span class="metric-icon bg-<?= $warna ?>-subtle text-<?= $warna ?>"><i class="fa-solid <?= $icon ?>"></i></span><div><small class="text-muted"><?= $label ?></small><h4 class="fw-bold mb-0"><?= $jumlah ?></h4></div></div></div></div><?php endforeach ?></div>
<section class="card ops-card mb-3"><div class="card-body p-3 p-md-4"><h6 class="fw-bold mb-1">Atur Akses Pertemuan</h6><p class="small text-muted">Gunakan untuk membuka kembali atau mengunci akses siswa pada pengajaran tertentu.</p><form method="post" class="row g-2 align-items-end" onsubmit="return confirm('Simpan perubahan akses pertemuan ini? Tindakan akan dicatat.');"><input type="hidden" name="csrf_token" value="<?= sanitize($_SESSION['csrf_token']) ?>"><input type="hidden" name="action" value="atur_akses"><div class="col-md-6"><label class="form-label small fw-semibold">Pengajaran</label><select name="pengajaran_id" class="form-select" required><?php foreach($pengajaran as $p): ?><option value="<?= (int)$p['id'] ?>"><?= sanitize($p['nama_guru'].' · '.$p['nama_mapel'].' · '.$p['nama_kelas'].' ('.$p['semester'].' / '.$p['tahun_ajaran'].')') ?></option><?php endforeach ?></select></div><div class="col-6 col-md-2"><label class="form-label small fw-semibold">Pertemuan</label><select name="pertemuan_ke" class="form-select"><?php for($i=1;$i<=20;$i++): ?><option value="<?= $i ?>"><?= $i ?></option><?php endfor ?></select></div><div class="col-6 col-md-2"><label class="form-label small fw-semibold">Status Baru</label><select name="status" class="form-select"><option value="Dibuka">Dibuka</option><option value="Dikunci">Dikunci</option></select></div><div class="col-md-2"><button class="btn btn-danger w-100"><i class="fa-solid fa-floppy-disk me-1"></i>Simpan</button></div></form></div></section>
<section class="card ops-card mb-3"><div class="card-body p-0"><div class="px-3 px-md-4 py-3 border-bottom"><h6 class="fw-bold mb-0">Sesi Absensi Terbuka</h6><small class="text-muted">Sesi kedaluwarsa diprioritaskan untuk diperiksa.</small></div><div class="table-responsive"><table class="table ops-table table-hover mb-0"><thead class="table-light"><tr><th class="ps-4">Pengajaran</th><th>Pertemuan</th><th>Jadwal</th><th>Progres</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($sesi_terbuka as $s): ?><tr class="<?= $s['kedaluwarsa']?'critical-row':'' ?>"><td class="ps-4"><strong><?= sanitize($s['nama_mapel']) ?></strong><br><small><?= sanitize($s['nama_kelas']) ?> · <?= sanitize($s['nama_guru']) ?></small></td><td><?= (int)$s['pertemuan_ke'] ?></td><td><small><?= date('d/m/Y H:i',strtotime($s['waktu_buka'])) ?><br>s.d. <?= date('d/m/Y H:i',strtotime($s['waktu_tutup'])) ?></small></td><td><?= (int)$s['tercatat'] ?>/<?= (int)$s['total_siswa'] ?></td><td><span class="badge <?= $s['kedaluwarsa']?'bg-danger':'bg-success' ?>"><?= $s['kedaluwarsa']?'Kedaluwarsa':'Aktif' ?></span></td><td><form method="post" onsubmit="return confirm('Tutup sesi ini? Siswa yang belum check-in akan menjadi Alpa.');"><input type="hidden" name="csrf_token" value="<?= sanitize($_SESSION['csrf_token']) ?>"><input type="hidden" name="action" value="tutup_sesi"><input type="hidden" name="sesi_id" value="<?= (int)$s['id'] ?>"><button class="btn btn-sm btn-danger"><i class="fa-solid fa-lock me-1"></i>Tutup</button></form></td></tr><?php endforeach ?><?php if(!$sesi_terbuka): ?><tr><td colspan="6" class="text-center text-muted py-5">Tidak ada sesi absensi terbuka.</td></tr><?php endif ?></tbody></table></div></div></section>
<section class="card ops-card mb-3"><div class="card-body p-0"><div class="px-3 px-md-4 py-3 border-bottom"><h6 class="fw-bold mb-0">Akses Pertemuan Sedang Dibuka</h6><small class="text-muted">Admin dapat mengunci langsung akses yang tidak seharusnya masih terbuka.</small></div><div class="table-responsive"><table class="table ops-table table-hover mb-0"><thead class="table-light"><tr><th class="ps-4">Pengajaran</th><th>Pertemuan</th><th>Dibuka Pada</th><th>Aksi</th></tr></thead><tbody><?php foreach($akses_terbuka as $a): ?><tr><td class="ps-4"><strong><?= sanitize($a['nama_mapel']) ?></strong><br><small><?= sanitize($a['nama_kelas']) ?> · <?= sanitize($a['nama_guru']) ?></small></td><td><span class="badge bg-success">Pertemuan <?= (int)$a['pertemuan_ke'] ?></span></td><td><?= $a['dibuka_pada']?date('d/m/Y H:i',strtotime($a['dibuka_pada'])):'-' ?></td><td><form method="post" onsubmit="return confirm('Kunci akses pertemuan ini untuk siswa?');"><input type="hidden" name="csrf_token" value="<?= sanitize($_SESSION['csrf_token']) ?>"><input type="hidden" name="action" value="atur_akses"><input type="hidden" name="pengajaran_id" value="<?= (int)$a['pengajaran_id'] ?>"><input type="hidden" name="pertemuan_ke" value="<?= (int)$a['pertemuan_ke'] ?>"><input type="hidden" name="status" value="Dikunci"><button class="btn btn-sm btn-outline-danger"><i class="fa-solid fa-lock me-1"></i>Kunci</button></form></td></tr><?php endforeach ?><?php if(!$akses_terbuka): ?><tr><td colspan="4" class="text-center text-muted py-4">Tidak ada akses pertemuan yang sedang dibuka.</td></tr><?php endif ?></tbody></table></div></div></section>
<div class="row g-3"><div class="col-xl-7"><section class="card ops-card h-100"><div class="card-body p-0"><div class="px-3 px-md-4 py-3 border-bottom"><h6 class="fw-bold mb-0">Sesi Tertutup Tidak Lengkap</h6><small class="text-muted">Siswa tanpa detail absensi dapat disinkronkan menjadi Alpa.</small></div><div class="table-responsive"><table class="table ops-table mb-0"><thead class="table-light"><tr><th class="ps-4">Sesi</th><th>Data</th><th>Aksi</th></tr></thead><tbody><?php foreach($sesi_tidak_lengkap as $s): ?><tr><td class="ps-4"><strong><?= sanitize($s['nama_mapel']) ?></strong><br><small><?= sanitize($s['nama_kelas']) ?> · P<?= (int)$s['pertemuan_ke'] ?> · <?= date('d/m/Y',strtotime($s['tanggal'])) ?></small></td><td><span class="text-danger"><?= (int)$s['tercatat'] ?>/<?= (int)$s['total_siswa'] ?></span></td><td><form method="post" onsubmit="return confirm('Sinkronkan siswa yang belum tercatat menjadi Alpa?');"><input type="hidden" name="csrf_token" value="<?= sanitize($_SESSION['csrf_token']) ?>"><input type="hidden" name="action" value="sinkron_sesi"><input type="hidden" name="sesi_id" value="<?= (int)$s['id'] ?>"><button class="btn btn-sm btn-warning"><i class="fa-solid fa-rotate me-1"></i>Sinkronkan</button></form></td></tr><?php endforeach ?><?php if(!$sesi_tidak_lengkap): ?><tr><td colspan="3" class="text-center text-muted py-4">Semua sesi tertutup sudah lengkap.</td></tr><?php endif ?></tbody></table></div></div></section></div>
<div class="col-xl-5"><section class="card ops-card h-100"><div class="card-body p-3 p-md-4"><div class="d-flex justify-content-between"><div><h6 class="fw-bold mb-1">Audit Operasional</h6><small class="text-muted">20 tindakan admin terbaru</small></div><a href="log_aktivitas.php?q=OPERASIONAL+ADMIN" class="btn btn-sm btn-outline-primary align-self-start">Semua Log</a></div><div class="mt-2"><?php foreach($audit_operasional as $log): ?><div class="audit-item"><strong class="small"><?= sanitize($log['username']?:'Admin') ?></strong><small class="text-muted float-end"><?= date('d/m/Y H:i',strtotime($log['created_at'])) ?></small><div class="small mt-1"><?= sanitize($log['aktivitas']) ?></div><code class="small"><?= sanitize($log['ip_address']) ?></code></div><?php endforeach ?><?php if(!$audit_operasional): ?><p class="text-muted text-center py-4 mb-0">Belum ada tindakan operasional.</p><?php endif ?></div></div></section></div></div>
